{"tool": "submit_job", "args": {"source": "import child_process from 'node:child_process';
import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';

export async function gate({ referenceDir, submissionDir }) {
  const nonce = crypto.randomBytes(32).toString('hex');
  const runnerPath = path.join(referenceDir, '_runner_' + nonce + '.mjs');
  const resultPath = path.join(referenceDir, '_result_' + nonce + '.json');
  const answerPath = path.join(submissionDir, 'answer.mjs');
  const pinnedPath = path.join(referenceDir, 'pinned-test-cases.txt');

  const runner = [
    "import fs from 'node:fs';",
    "import vm from 'node:vm';",
    "import assert from 'node:assert/strict';",
    'const NONCE = ' + JSON.stringify(nonce) + ';',
    'const answerPath = ' + JSON.stringify(answerPath) + ';',
    'const pinnedPath = ' + JSON.stringify(pinnedPath) + ';',
    'const resultPath = ' + JSON.stringify(resultPath) + ';',
    'function report(obj) {',
    '  const payload = JSON.stringify({ nonce: NONCE, ...obj });',
    '  try { fs.writeSync(3, payload); } catch {}',
    '  try { fs.writeFileSync(resultPath, payload); } catch {}',
    '}',
    'function toScript(src) {',
    "  let s = String(src).replace(/^\\uFEFF/, '').replace(/^#![\\s\\S]*?\\n/, '');",
    '  s = s.replace(/export\\s*\\{([^}]*)\\}\\s*;?/g, (_, inner) => {',
    "    return inner.split(',').map((part) => {"," ,
    "      const t = part.trim();",
    "      if (!t) return '';",
    '      const bits = t.split(/\\s+as\\s+/);',
    "      if (bits.length === 2) return 'var ' + bits[1].trim() + ' = ' + bits[0].trim() + ';';",
    "      return '';",
    "    }).join('\\n');",
    '  });',
    "  s = s.replace(/export\\s+default\\s+async\\s+function\\s+([A-Za-z_$][\\w$]*)/g, 'async function $1');",
    "  s = s.replace(/export\\s+default\\s+function\\s+([A-Za-z_$][\\w$]*)/g, 'function $1');",
    "  s = s.replace(/export\\s+default\\s+async\\s+function\\b/g, 'async function __default');",
    "  s = s.replace(/export\\s+default\\s+function\\b/g, 'function __default');",
    "  s = s.replace(/export\\s+async\\s+function\\s+/g, 'async function ');",
    "  s = s.replace(/export\\s+function\\s+/g, 'function ');",
    "  s = s.replace(/export\\s+(?:const|let|var)\\s+/g, 'var ');",
    "  s = s.replace(/export\\s+default\\s+/g, 'var __default = ');",
    '  s += "\\n;__fn = (typeof dedupeSorted === \\"function\\") ? dedupeSorted : ((typeof __default === \\"function\\") ? __default : __fn);";',
    '  return s;',
    '}',
    'let src = "";',
    'let pinned = "";',
    "try { src = fs.readFileSync(answerPath, 'utf8'); } catch (e) { report({ ok: false, reason: 'cannot read answer.mjs' }); process.exit(0); }",
    "try { pinned = fs.readFileSync(pinnedPath, 'utf8'); } catch (e) { report({ ok: false, reason: 'cannot read pinned-test-cases.txt' }); process.exit(0); }",
    'const sandbox = {',
    '  Array, Object, Number, String, Boolean, Math, JSON, Date, RegExp,',
    '  Map, Set, WeakMap, WeakSet, Promise, Symbol, Error, TypeError,',
    '  RangeError, SyntaxError, URIError, EvalError, Infinity, NaN,',
    '  parseInt, parseFloat, isNaN, isFinite,',
    '  Uint8Array, Int8Array, Uint16Array, Int16Array, Uint32Array, Int32Array,',
    '  Float32Array, Float64Array, Uint8ClampedArray, ArrayBuffer, DataView,',
    '  BigInt, Proxy, Reflect,',
    '  encodeURI, decodeURI, encodeURIComponent, decodeURIComponent,',
    '  console: { log() {}, warn() {}, error() {}, info() {}, debug() {}, trace() {} },',
    '  __fn: undefined,',
    '};',
    'sandbox.globalThis = sandbox;',
    'sandbox.global = sandbox;',
    'try {',
    "  vm.runInNewContext(toScript(src), sandbox, { timeout: 4000, filename: 'answer.mjs' });",
    '} catch (e) {',
    "  report({ ok: false, reason: 'load error: ' + (e && e.message) });",
    '  process.exit(0);',
    '}',
    'const dedupeSorted = sandbox.__fn;',
    "if (typeof dedupeSorted !== 'function') { report({ ok: false, reason: 'dedupeSorted is not a function' }); process.exit(0); }",
    'let planned = 0;',
    'let completed = 0;',
    'const failures = [];',
    'function test(name, fn) {',
    '  planned += 1;',
    '  try { fn(); completed += 1; }',
    "  catch (e) { failures.push(String(name) + ': ' + (e && e.message ? e.message : e)); }",
    '}',
    'try {',
    "  const run = new Function('test', 'assert', 'dedupeSorted', pinned);",
    '  run(test, assert, dedupeSorted);',
    '} catch (e) {',
    "  report({ ok: false, reason: 'suite execution error: ' + (e && e.message), planned, completed, failures });",
    '  process.exit(0);',
    '}',
    'if (planned < 8 || completed !== planned || failures.length) {',
    "  report({ ok: false, reason: failures.join('; ') || ('incomplete suite planned=' + planned + ' completed=' + completed), planned, completed, failures });",
    '  process.exit(0);',
    '}',
    'report({ ok: true, planned, completed });',
    'process.exit(0);',
  ].join('\n');

  fs.writeFileSync(runnerPath, runner, 'utf8');

  const outcome = await new Promise((resolve) => {
    let fd3 = '';
    const child = child_process.spawn(process.execPath, [runnerPath], {
      stdio: ['ignore', 'ignore', 'ignore', 'pipe'],
      timeout: 12000,
      env: {},
      cwd: referenceDir,
    });
    if (child.stdio[3]) {
      child.stdio[3].setEncoding('utf8');
      child.stdio[3].on('data', (d) => { fd3 += d; });
    }
    const done = (extra) => resolve({ fd3, ...extra });
    child.on('error', (err) => done({ err: String(err && err.message || err) }));
    child.on('close', (code, signal) => done({ code, signal }));
  });

  function parsePayload() {
    const candidates = [];
    if (outcome.fd3) candidates.push(outcome.fd3);
    try { candidates.push(fs.readFileSync(resultPath, 'utf8')); } catch {}
    for (const c of candidates) {
      try {
        const obj = JSON.parse(c);
        if (obj && obj.nonce === nonce) return obj;
      } catch {}
    }
    return null;
  }

  const payload = parsePayload();
  if (!payload) {
    return { accept: false, reason: 'could not establish that the pinned suite ran to completion' };
  }
  if (!payload.ok || payload.completed !== payload.planned || payload.planned < 8) {
    return { accept: false, reason: String(payload.reason || 'pinned tests failed') };
  }
  return { accept: true, reason: 'all ' + payload.completed + ' pinned tests passed' };
}
"}, "rationale": "Submit a sandboxed gate that runs the pinned suite in a child process and only accepts on a nonce-authenticated completion record.", "friction": {"could_not_express": null, "forced_conversion": false, "conversion_reason": null, "missing_information": null, "decision_confidence": "high"}}
